    ('322', 35.257068, 129.216415, '흙시루', 'Hurgsiru', 'WHY_VISIT', '{"reasons": [{"type": "운영·접근 편의", "note": "황토벽과 초가지붕 등 전통 한옥 가옥과 야생화 정원이 어우러진 고즈넉한 공간 분위기"}, {"type": "맛 자체", "note": "단호박 오리구이, 녹두오리탕 등 특색 있는 보양 한식 요리"}], "sources": ["https://www.siksinhot.com/P/350614", "https://www.menupan.com/restaurant/onepage.asp?acode=H601449"]}'),
    ('322', 35.257068, 129.216415, '흙시루', 'Hurgsiru', 'OPENING_HOURS', '{"status": "PARSED", "byDay": {"mon": [], "tue": [["11:00", "21:00"]], "wed": [["11:00", "21:00"]], "thu": [["11:00", "21:00"]], "fri": [["11:00", "21:00"]], "sat": [["11:00", "21:00"]], "sun": [["11:00", "21:00"]]}, "closedDays": ["mon"], "notes": ["월요일 정기휴무"], "raw": {"hoursField": "research", "hoursValue": "화요일~일요일 11:00 ~ 21:00 (월요일 정기휴무)"}}'),
    ('323', 35.0982708, 129.0326242, '서울삼계탕', 'Seoul Samgyetang', 'WHY_VISIT', '{"reasons": [{"type": "오랜 역사", "note": "1960년부터 이어져 온 60년 이상의 오랜 역사와 대를 잇는 전통 노포 삼계탕 맛집"}, {"type": "맛 자체", "note": "약재를 넣고 진하게 고아낸 영계 육수와 소면을 말아먹는 전통적인 맛"}, {"type": "운영·접근 편의", "note": "남포역 1번 출구 도보 3분 거리의 남포동 중심가에 위치한 편리한 접근성"}], "sources": ["https://korean.visitkorea.or.kr"]}'),
    ('323', 35.0982708, 129.0326242, '서울삼계탕', 'Seoul Samgyetang', 'OPENING_HOURS', '{"status": "PARSED", "byDay": {"mon": [["09:30", "22:00"]], "tue": [["09:30", "22:00"]], "wed": [["09:30", "22:00"]], "thu": [["09:30", "22:00"]], "fri": [["09:30", "22:00"]], "sat": [["09:30", "22:00"]], "sun": [["09:30", "22:00"]]}, "notes": ["연중무휴"], "raw": {"hoursField": "research", "hoursValue": "09:30 ~ 22:00 (연중무휴)"}}'),
    ('324', 35.145081, 129.028805, '서가네', 'Seogane', 'WHY_VISIT', '{"reasons": [{"type": "운영·접근 편의", "note": "도심 속 계곡 감성과 숲뷰 야외석, 족구장 및 대규모 인원 수용 가능한 단체 편의 시설"}, {"type": "맛 자체", "note": "오리불고기, 오리백숙 등 전통적인 가야공원 오리 요리 전문"}], "sources": ["https://nett.kr", "https://knn.co.kr", "https://pknu.ac.kr"]}'),
    ('324', 35.145081, 129.028805, '서가네', 'Seogane', 'OPENING_HOURS', '{"status": "PARSED", "byDay": {"mon": [["10:30", "22:00"]], "tue": [["10:30", "22:00"]], "wed": [["10:30", "22:00"]], "thu": [["10:30", "22:00"]], "fri": [["10:30", "22:00"]], "sat": [["10:30", "22:00"]], "sun": [["10:30", "22:00"]]}, "notes": ["야외석 등 운영 시간에 차이가 있을 수 있음"], "raw": {"hoursField": "research", "hoursValue": "매일 10:30 ~ 22:00 (야외석 등 운영 시간에 차이가 있을 수 있음)"}}'),
    ('325', 35.079767, 128.903796, '산골애', 'Sangole', 'WHY_VISIT', '{"reasons": [{"type": "맛 자체", "note": "쫀득한 누룽지와 부드러운 오리고기의 조화 및 식전 통닭, 식후 홍시 샤베트 코스 구성"}, {"type": "운영·접근 편의", "note": "개별 룸과 유아용 의자, 건물 주차장이 완비되어 가족 외식 및 단체 모임에 최적화"}], "sources": ["https://www.siksinhot.com/P/1786797333007005", "https://tistory.com"]}'),
    ('325', 35.079767, 128.903796, '산골애', 'Sangole', 'OPENING_HOURS', '{"status": "PARSED", "byDay": {"mon": [], "tue": [["11:30", "22:00"]], "wed": [["11:30", "22:00"]], "thu": [["11:30", "22:00"]], "fri": [["11:30", "22:00"]], "sat": [["11:30", "22:00"]], "sun": [["11:30", "22:00"]]}, "closedDays": ["mon"], "notes": ["브레이크타임 15:00 ~ 17:00, 매주 월요일 정기휴무"], "raw": {"hoursField": "research", "hoursValue": "11:30 ~ 22:00 (브레이크타임 15:00 ~ 17:00, 매주 월요일 정기휴무)"}}'),
    ('326', 35.169521, 129.119584, '장수삼', 'Jangsusam', 'WHY_VISIT', '{"reasons": [{"type": "가격·가성비", "note": "어머니 손맛 같은 깔끔하고 담백한 가정식 삼계탕을 부담 없는 저렴한 가격으로 편하게 먹을 수 있음"}, {"type": "맛 자체", "note": "깔끔하고 담백하게 우려낸 삼계탕 본연의 맛"}], "sources": ["https://www.trip.com", "https://www.siksinhot.com"]}'),
    ('326', 35.169521, 129.119584, '장수삼', 'Jangsusam', 'OPENING_HOURS', '{"status": "PARSED", "byDay": {"mon": [["11:00", "20:00"]], "tue": [["11:00", "20:00"]], "wed": [["11:00", "20:00"]], "thu": [["11:00", "20:00"]], "fri": [["11:00", "20:00"]], "sat": [["11:00", "20:00"]], "sun": [["11:00", "20:00"]]}, "raw": {"hoursField": "research", "hoursValue": "11:00 ~ 20:00"}}'),
    ('327', 35.139004, 129.105022, '옹기촌', 'Onggichon', 'WHY_VISIT', '{"reasons": [{"type": "맛 자체", "note": "유황오리 허브구이 및 오리백숙 등 오리 요리 전문 식당으로 이용됨"}], "sources": ["https://www.saramin.co.kr", "https://www.daum.net"]}')
) AS seed(no, lat, lng, token_ko, token_en, feature_type, value)
JOIN place p
  ON abs(p.lat - seed.lat) < 0.00135
 AND abs(p.lng - seed.lng) < 0.00165
 AND p.category = 'FOOD'
 AND (REPLACE(p.name_ko, ' ', '') LIKE '%' || REPLACE(seed.token_ko, ' ', '') || '%'
      OR p.name_ko ILIKE '%' || seed.token_en || '%'
      OR p.name_en ILIKE '%' || seed.token_en || '%')
WHERE NOT EXISTS (
    SELECT 1 FROM place_feature f
    WHERE f.place_id = p.place_id
      AND f.feature_type = seed.feature_type
)
ORDER BY p.place_id, seed.feature_type, seed.no;

